## Recommended Mitigation Steps
### Adjust Inheritance Order
Ensure ERC721Enumerable is inherited directly to maintain the correct method resolution order.
### Correct super Calls
Update the super calls in the overridden functions to correctly reference ERC721Enumerable.
```Solidity
contract NonfungiblePositionManager is
    Multicall,
    PeripheryImmutableState,
    PoolInitializer,
    LiquidityManagement,
    PeripheryValidation,
    ERC721Enumerable,
    INonfungiblePositionManager
{
    // ...

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override(ERC721Enumerable) returns (address) {
        return super._update(to, tokenId, auth);
    }

    function _increaseBalance(address account, uint128 value) internal override(ERC721Enumerable) {
        super._increaseBalance(account, value);
    }

    // ...
}
